// ValidateCreateProfileRequestBody runs the validations defined on
// CreateProfileRequestBody
func ValidateCreateProfileRequestBody(body *CreateProfileRequestBody) (err error) {
	if body.Name == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("name", "body"))
	}
	if body.Provider == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("provider", "body"))
	}
	if body.Settings == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("settings", "body"))
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 1, true))
		}
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) > 100 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 100, false))
		}
	}
	if body.Provider != nil {
		if !(*body.Provider == "bedrock" || *body.Provider == "vertex" || *body.Provider == "gateway") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.provider", *body.Provider, []any{"bedrock", "vertex", "gateway"}))
		}
	}
	if body.Settings != nil {
		if err2 := ValidateInferenceProfileSettingsRequestBody(body.Settings); err2 != nil {
			err = goa.MergeErrors(err, err2)
		}
	}
	return
}

